#include <vector>
#include <queue>
#include <tuple>
using namespace std;

class Solution {
public:
    int getFood(vector<vector<char>>& grid) {
        int m = grid.size();
        int n = grid[0].size();
        queue<tuple<int, int, int>> q;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] == '*') {
                    q.push({r, c, 0});
                    grid[r][c] = 'X';
                    break;
                }
            }
            if (!q.empty()) break;
        }

        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!q.empty()) {
            auto [r, c, d] = q.front();
            q.pop();
            for (auto& dir : dirs) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    if (grid[nr][nc] == '#') return d + 1;
                    if (grid[nr][nc] == 'O') {
                        grid[nr][nc] = 'X';
                        q.push({nr, nc, d + 1});
                    }
                }
            }
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int getFood(char[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        Queue<int[]> q = new LinkedList<>();
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] == '*') {
                    q.offer(new int[]{r, c, 0});
                    grid[r][c] = 'X';
                    break;
                }
            }
            if (!q.isEmpty()) break;
        }

        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!q.isEmpty()) {
            int[] curr = q.poll();
            int r = curr[0], c = curr[1], d = curr[2];
            for (int[] dir : dirs) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    if (grid[nr][nc] == '#') return d + 1;
                    if (grid[nr][nc] == 'O') {
                        grid[nr][nc] = 'X';
                        q.offer(new int[]{nr, nc, d + 1});
                    }
                }
            }
        }
        return -1;
    }
}

