var getFood = function(grid) {
    const m = grid.length;
    const n = grid[0].length;
    const q = [];
    for (let r = 0; r < m; ++r) {
        for (let c = 0; c < n; ++c) {
            if (grid[r][c] === '*') {
                q.push([r, c, 0]);
                grid[r][c] = 'X';
                break;
            }
        }
        if (q.length > 0) break;
    }

    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    let head = 0;
    while (head < q.length) {
        const [r, c, d] = q[head++];
        for (const [dr, dc] of dirs) {
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                if (grid[nr][nc] === '#') return d + 1;
                if (grid[nr][nc] === 'O') {
                    grid[nr][nc] = 'X';
                    q.push([nr, nc, d + 1]);
                }
            }
        }
    }
    return -1;
};
